// Package tpl is the templ v0.3.1020 baseline of the ADR-0003 benchmarks. The
// *_templ.go files are generated by the pinned templ CLI: templ generate.
package tpl

import (
	"context"
	"io"

	"github.com/a-h/templ"
)

// trustedScript writes a trusted script element, as templ.Raw would write
// trusted markup: templ escapes interpolations inside script elements, so a
// verbatim script body needs a component.
func trustedScript(js string) templ.Component {
	return templ.ComponentFunc(func(_ context.Context, w io.Writer) error {
		if _, err := io.WriteString(w, "<script>"); err != nil {
			return err
		}
		if _, err := io.WriteString(w, js); err != nil {
			return err
		}
		_, err := io.WriteString(w, "</script>")
		return err
	})
}
